#pragma once
#include "FillProjection.hh"
#include <QJsonArray>
#include <QJsonObject>
#include <QUuid>
namespace bts {
inline QJsonValue fill_texture_json(const std::shared_ptr<const FillTexture> &texture){if(!texture)return QJsonValue::Null;QJsonObject result{{"asset",QString::fromStdString(texture->asset)},{"sha256",QString::fromStdString(texture->hash)},{"name",QString::fromStdString(texture->name)},{"width",texture->width},{"height",texture->height},{"raw",texture->raw}};if(!texture->source_space.empty())result["source_space"]=QString::fromStdString(texture->source_space);if(texture->tiles){QJsonArray members;for(const auto &[tile,image]:*texture->tiles)members.append(QJsonObject{{"tile",tile},{"image",fill_texture_json(image)}});result["tiles"]=members;}return result;}
inline std::shared_ptr<const FillTexture> read_fill_texture_json(const QJsonValue &value,bool allow_sequence=true){if(value.isNull()||value.isUndefined())return {};if(!value.isObject())throw std::invalid_argument("Invalid fill texture descriptor");const auto data=value.toObject();auto texture=std::make_shared<FillTexture>();texture->asset=data["asset"].toString().toStdString();texture->hash=data["sha256"].toString().toStdString();texture->name=data["name"].toString().toStdString();texture->width=data["width"].toInt();texture->height=data["height"].toInt();if(data.contains("raw")&&!data["raw"].isBool())throw std::invalid_argument("Invalid texture interpretation");texture->raw=data["raw"].toBool(false);if(data.contains("source_space")&&!data["source_space"].isString())throw std::invalid_argument("Invalid source color-space name");texture->source_space=data["source_space"].toString().toStdString();
 if(data.contains("tiles")){if(!allow_sequence||!data["tiles"].isArray()||data["tiles"].toArray().isEmpty())throw std::invalid_argument("Invalid texture sequence descriptor");require_texture_ram(resource_product(data["tiles"].toArray().size(),sizeof(FillTexture)+sizeof(std::pair<const int,std::shared_ptr<const FillTexture>>)+4*sizeof(void *)),"Texture sequence metadata");auto members=std::make_shared<std::map<int,std::shared_ptr<const FillTexture>>>();for(const auto &entry:data["tiles"].toArray()){const auto item=entry.toObject();const int tile=item["tile"].toInt();if(!item["tile"].isDouble()||item["tile"].toDouble()!=tile||tile<1001||tile>9999||!members->emplace(tile,[&]{auto member=read_fill_texture_json(item["image"],false);if(member&&member->hash==texture->hash){auto distinct=std::make_shared<FillTexture>(*member);distinct->storage_key=texture->hash+":tile:"+std::to_string(tile);return std::shared_ptr<const FillTexture>(std::move(distinct));}return member;}()).second)throw std::invalid_argument("Invalid/duplicate texture sequence tile");}texture->tiles=std::move(members);texture->storage_key=texture->tiles->begin()->second->storage_key;}
 texture->validate();if(QUuid(QString::fromStdString(texture->asset)).isNull()||data["width"].toDouble()!=texture->width||data["height"].toDouble()!=texture->height||std::any_of(texture->hash.begin(),texture->hash.end(),[](char c){return !(c>='0'&&c<='9')&&!(c>='a'&&c<='f');}))throw std::invalid_argument("Invalid fill texture identity");return texture;}
inline QJsonArray fill_channel_textures_json(const FillProjection &p){QJsonArray result;for(int channel=1;channel<15;++channel)result.append(fill_texture_json(fill_channel_texture(p,channel)));return result;}
inline void read_fill_channel_textures(FillProjection &p,const QJsonValue &value){if(!value.isArray()||value.toArray().size()!=14)throw std::invalid_argument("Invalid fill channel resources");const auto array=value.toArray();for(int i=0;i<14;++i){auto &texture=fill_channel_texture(p,i+1);texture=read_fill_texture_json(array[i]);if(texture&&!texture->raw)throw std::invalid_argument("Data channel texture must use Non-Color interpretation");}}
inline QJsonArray fill_alpha_mask_json(const FillProjection &p){QJsonArray result;for(bool value:p.alpha_mask)result.append(value);return result;}
inline void read_fill_alpha_mask(FillProjection &p,const QJsonValue &value){if(!value.isArray()||value.toArray().size()!=15)throw std::invalid_argument("Invalid texture alpha policy");const auto array=value.toArray();for(int c=0;c<15;++c){if(!array[c].isBool())throw std::invalid_argument("Invalid texture alpha policy");p.alpha_mask[c]=array[c].toBool();}}
inline QJsonValue fill_anchors_json(const FillProjection &p){if(!fill_has_anchors(p))return QJsonValue::Undefined;QJsonArray result;for(const auto &ref:p.anchors)result.append(ref.source.isNull()?QJsonValue(QJsonValue::Null):QJsonValue(anchor_reference_json(ref)));return result;}
inline void read_fill_anchors(FillProjection &p,const QJsonValue &value){if(value.isUndefined()||value.isNull())return;if(!value.isArray()||value.toArray().size()!=15)throw std::invalid_argument("Invalid fill anchor resources");const auto array=value.toArray();for(int c=0;c<15;++c){p.anchors[c]=array[c].isNull()?AnchorReference{}:read_anchor_reference(array[c]);if(!array[c].isNull()&&p.anchors[c].source.isNull())throw std::invalid_argument("Fill anchor source is missing");}validate_fill_projection(p);}

}
